     1	import java.math.BigDecimal;
     2	import java.math.RoundingMode;
     3	import java.util.List;
     4	
     5	public class ClaimOffice {
     6	
     7	    private static final int PROCESSING_FEE_IN_G = 5;
     8	
     9	    private final PolicyWideModifiers policyWideModifiers;
    10	
    11	    public ClaimOffice(Customer customer) {
    12	        this.policyWideModifiers = new PolicyWideModifiers(customer);
    13	    }
    14	
    15	    /**
    16	     * The policy base premium is the sum of the base premiums of the main items
    17	     * and of the components, each priced by its own MHPCO pricing policy.
    18	     *
    19	     * The MHPCO names this amount in its own rules, so it is observable inside
    20	     * the domain; it is not part of what the office offers a caller, which is
    21	     * a quote.
    22	     */
    23	    int basePremium(List<Item> items) {
    24	        return MainItemPricing.mainItemsBasePremium(items)
    25	                + ComponentPricing.componentsBasePremium(items);
    26	    }
    27	
    28	    /**
    29	     * Item-specific modifiers apply to the base premium of the affected item,
    30	     * not to the policy total.
    31	     */
    32	    BigDecimal premiumAfterItemModifiers(List<Item> items) {
    33	        return BigDecimal.valueOf(basePremium(items))
    34	                .add(ItemRiskSurcharges.totalItemSurcharges(items));
    35	    }
    36	
    37	    /**
    38	     * The MHPCO issues a policy over the items it has agreed to cover.
    39	     */
    40	    public Policy insure(List<Item> items) {
    41	        return new Policy(accepted(items));
    42	    }
    43	
    44	    /**
    45	     * The items the MHPCO agrees to cover. The office declines the whole
    46	     * request rather than working around an item it does not insure, and it
    47	     * decides this the same way whether it is quoting for the items or issuing
    48	     * a policy over them.
    49	     */
    50	    private static List<Item> accepted(List<Item> items) {
    51	        InsurableItems.requireAllInsurable(items);
    52	        return items;
    53	    }
    54	
    55	    /**
    56	     * What the MHPCO would charge to insure these items, priced only for items
    57	     * the office has accepted.
    58	     *
    59	     * The MHPCO assembles the premium from a base premium and two families of
    60	     * modifier. Neither family is measured against the other's amounts: the
    61	     * item-specific risk surcharges are measured against the base premium of
    62	     * each affected item, the policy-wide modifiers against the policy base
    63	     * premium as a whole. Both are therefore added to the policy base premium
    64	     * side by side rather than in sequence, and the processing fee is added at
    65	     * the very end.
    66	     */
    67	    public int quote(List<Item> items) {
    68	        List<Item> insuredItems = accepted(items);
    69	        BigDecimal policyBasePremium = BigDecimal.valueOf(basePremium(insuredItems));
    70	        BigDecimal quotedPremium = premiumAfterItemModifiers(insuredItems)
    71	                .add(policyWideModifiers.totalPolicyModifiers(policyBasePremium))
    72	                .add(BigDecimal.valueOf(PROCESSING_FEE_IN_G));
    73	        policyWideModifiers.recordContractIssued();
    74	        return roundedUpInTheMhpcoFavour(quotedPremium);
    75	    }
    76	
    77	    /**
    78	     * All amounts are rounded to whole G in the MHPCO's favour: a premium the
    79	     * customer owes is rounded up.
    80	     */
    81	    private static int roundedUpInTheMhpcoFavour(BigDecimal premium) {
    82	        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
    83	    }
    84	}
