===== Percentage.java =====
     1	import java.math.BigDecimal;
     2	import java.math.MathContext;
     3	
     4	/**
     5	 * A percentage of an amount in G, as the MHPCO measures every premium
     6	 * modifier: a risk surcharge against an item's base premium, a discount or
     7	 * assessment surcharge against the policy premium.
     8	 *
     9	 * This is the one place that says how the MHPCO turns a modifier percentage
    10	 * into an amount, so a change to that arithmetic is made here and nowhere
    11	 * else.
    12	 */
    13	public final class Percentage {
    14	
    15	    private static final BigDecimal WHOLE = BigDecimal.valueOf(100);
    16	
    17	    /**
    18	     * The MHPCO keeps intermediate amounts as fractions and rounds only the
    19	     * final premium or payout, so a modifier amount is carried at a precision
    20	     * far beyond the whole G it will finally be rounded to. Stating the
    21	     * precision here keeps a modifier whose share does not divide evenly -- a
    22	     * third-share surcharge, say -- an arithmetic detail rather than a failed
    23	     * quote.
    24	     */
    25	    private static final MathContext KEPT_AS_A_FRACTION = MathContext.DECIMAL64;
    26	
    27	    private Percentage() {
    28	    }
    29	
    30	    public static BigDecimal of(BigDecimal amountInG, int percent) {
    31	        return amountInG.multiply(BigDecimal.valueOf(percent)).divide(WHOLE, KEPT_AS_A_FRACTION);
    32	    }
    33	
    34	    public static BigDecimal of(int amountInG, int percent) {
    35	        return of(BigDecimal.valueOf(amountInG), percent);
    36	    }
    37	}
