     1	import java.util.List;
     2	
     3	/**
     4	 * A policy the MHPCO has issued over a list of insured items. The insurance
     5	 * sum is what the covered items are insured for; the MHPCO pays out at most
     6	 * twice that sum over the life of the policy.
     7	 */
     8	public final class Policy {
     9	
    10	    private static final int CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    11	
    12	    private final List<Item> insuredItems;
    13	
    14	    public Policy(List<Item> insuredItems) {
    15	        this.insuredItems = List.copyOf(insuredItems);
    16	    }
    17	
    18	    public int insuranceSum() {
    19	        return insuredItems.stream()
    20	                .mapToInt(InsuranceValues::insuranceValueOf)
    21	                .sum();
    22	    }
    23	
    24	    /**
    25	     * The most the MHPCO will pay out over the life of this policy: twice the
    26	     * insurance sum. No claim has yet been made against a policy, so this is
    27	     * the whole cap; what remains of it after claims is a claim's concern.
    28	     */
    29	    public int cap() {
    30	        return CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum();
    31	    }
    32	}
===== PolicyWideModifiers.java =====
     1	import java.math.BigDecimal;
     2	
     3	/**
     4	 * The MHPCO's policy-wide premium modifiers. Unlike the item-specific risk
     5	 * surcharges, these are measured against the policy premium as a whole and
     6	 * depend on the customer's history with the MHPCO rather than on any item.
     7	 *
     8	 * This is the one place that says which modifiers are policy-wide: a further
     9	 * policy-wide modifier is added here and nowhere else. So far the MHPCO grants
    10	 * the loyalty discount and charges the initial assessment surcharge.
    11	 */
    12	public final class PolicyWideModifiers {
    13	
    14	    private static final int LOYALTY_YEARS = 2;
    15	
    16	    private static final int LOYALTY_DISCOUNT_PERCENT = 20;
    17	
    18	    private static final int INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
    19	
    20	    private static final int FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
    21	
    22	    private final Customer customer;
    23	
    24	    private int contractsIssued;
    25	
    26	    public PolicyWideModifiers(Customer customer) {
    27	        this.customer = customer;
    28	    }
    29	
    30	    /**
    31	     * The net effect of every policy-wide modifier on a policy premium:
    32	     * positive amounts are charged to the customer, negative amounts are
    33	     * granted to the customer. Each modifier states its own direction, so this
    34	     * sum says only which modifiers the MHPCO applies policy-wide.
    35	     */
    36	    public BigDecimal totalPolicyModifiers(BigDecimal policyPremium) {
    37	        return initialAssessmentSurcharge(policyPremium)
    38	                .add(loyaltyDiscount(policyPremium))
    39	                .add(followUpContractDiscount(policyPremium));
    40	    }
    41	
    42	    /**
    43	     * The MHPCO notes that a contract has been issued to this customer. Every
    44	     * later contract is a follow-up contract, which is what the follow-up
    45	     * contract discount is measured against.
    46	     */
    47	    public void recordContractIssued() {
    48	        contractsIssued++;
    49	    }
    50	
    51	    /**
    52	     * Customers receive a 15 % discount on each contract after their first.
    53	     */
    54	    private BigDecimal followUpContractDiscount(BigDecimal policyPremium) {
    55	        if (!hasAPreviousContract()) {
    56	            return BigDecimal.ZERO;
    57	        }
    58	        return Percentage.of(policyPremium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT).negate();
    59	    }
    60	
    61	    private boolean hasAPreviousContract() {
    62	        return contractsIssued > 0;
    63	    }
    64	
    65	    /**
    66	     * Long-standing customers -- 2 or more years of business with the MHPCO --
    67	     * receive a 20 % loyalty discount on the policy premium.
    68	     */
    69	    private BigDecimal loyaltyDiscount(BigDecimal policyPremium) {
    70	        if (!isLongStandingCustomer()) {
    71	            return BigDecimal.ZERO;
    72	        }
    73	        return Percentage.of(policyPremium, LOYALTY_DISCOUNT_PERCENT).negate();
    74	    }
    75	
    76	    /**
    77	     * The MHPCO counts a customer as long-standing from 2 full years of
    78	     * business onwards; a customer in their second year is still a newcomer.
    79	     */
    80	    private boolean isLongStandingCustomer() {
    81	        return customer.yearsWithMHPCO() >= LOYALTY_YEARS;
    82	    }
    83	
    84	    /**
    85	     * Every item in a quote is treated as a first insurance, regardless of the
    86	     * customer's history with the MHPCO, and carries a 10 % initial assessment
    87	     * surcharge on the policy premium.
    88	     */
    89	    private BigDecimal initialAssessmentSurcharge(BigDecimal policyPremium) {
    90	        return Percentage.of(policyPremium, INITIAL_ASSESSMENT_SURCHARGE_PERCENT);
    91	    }
    92	
    93	}

